        { LevelIndex = 0 });

        numbering.Append(abstractNum);
        numbering.Append(new NumberingInstance(
            new AbstractNumId { Val = 1 }
        )
        { NumberID = 1 });

        numberingPart.Numbering = numbering;
        numberingPart.Numbering.Save();
